import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('svc-reader', 'svc@corp.internal', 'reader', 'sk-reader-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    key = request.headers.get('X-API-Key', '')
    if not key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = dict(user)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username pattern. Supports partial matching."""
    query = request.args.get('q', '')
    role_filter = request.args.get('role', '')

    # Build dynamic query for flexible searching
    sql = "SELECT id, username, email, role FROM users WHERE username LIKE '%" + query + "%'"

    if role_filter:
        sql += " AND role = '" + role_filter + "'"

    db = get_db()
    try:
        results = db.execute(sql).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        # Log the error for debugging
        db.execute('INSERT INTO audit_log (action, details) VALUES (?, ?)',
                   ('search_error', str(e)))
        db.commit()
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    data = request.get_json()
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, email, role, api_key) VALUES (?, ?, ?, ?)',
                   (data['username'], data['email'], data.get('role', 'user'), data.get('api_key', '')))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'db': os.path.exists(DATABASE)})

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
